{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "strength-l4l5-12wk",
    "name": "12-Week General Strength — Post L4-L5 Herniation",
    "description": "A 12-week full-gym strength programme for a 42-year-old male desk worker recovering from L4-L5 disc herniation. Spine-sparing principles throughout: no heavy axial spinal loading, no loaded spinal flexion. Hip-hinge patterns use Romanian deadlift and trap-bar variations rather than conventional barbell deadlift. Squatting is goblet/front-loaded. Core work is anti-flexion and anti-rotation only. Three training days per week with progressive overload across four 3-week blocks.",
    "type": "workout",
    "visibility": "template",
    "metadata": {
      "created_at": "2025-01-01T00:00:00Z",
      "updated_at": "2025-01-01T00:00:00Z",
      "created_by": "fitness-ai",
      "tags": ["strength", "back-rehab", "spine-sparing", "intermediate", "full-gym", "12-week"],
      "difficulty": "intermediate",
      "language": "en",
      "estimated_duration_days": 84
    },
    "goals": [
      {
        "id": "goal-general-strength",
        "type": "primary",
        "category": "strength",
        "name": "Build general strength",
        "description": "Progressively increase strength across major movement patterns while protecting the lumbar spine.",
        "target": {
          "metric": "session_rpe_avg",
          "target_value": 7,
          "unit": "rpe",
          "measurement_type": "absolute"
        }
      },
      {
        "id": "goal-core-stability",
        "type": "secondary",
        "category": "injury_prevention",
        "name": "Develop lumbar-spine stability",
        "description": "Build anti-flexion and anti-rotation core strength to support long-term spinal health."
      },
      {
        "id": "goal-posture",
        "type": "secondary",
        "category": "posture",
        "name": "Improve postural endurance",
        "description": "Address desk-worker posture deficits: thoracic mobility, hip flexor length, scapular retraction strength."
      }
    ],
    "requirements": {
      "min_age": 18,
      "fitness_level": ["beginner", "intermediate"],
      "equipment": [
        { "id": "eq-barbell", "name": "Barbell", "required": false, "alternatives": ["trap_bar"] },
        { "id": "eq-trap-bar", "name": "Trap Bar / Hex Bar", "required": true },
        { "id": "eq-dumbbells", "name": "Dumbbells", "required": true },
        { "id": "eq-cables", "name": "Cable Machine", "required": true },
        { "id": "eq-pulldown", "name": "Lat Pulldown / Assisted Pull-up Machine", "required": true },
        { "id": "eq-bench", "name": "Adjustable Bench", "required": true },
        { "id": "eq-bands", "name": "Resistance Bands", "required": false },
        { "id": "eq-foam-roller", "name": "Foam Roller", "required": true }
      ],
      "contraindications": [
        {
          "condition": "icd10:M51.1",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": ["conventional_deadlift", "barbell_back_squat", "good_morning", "sit_up", "crunch", "jefferson_curl"]
        },
        {
          "condition": "heavy_axial_spinal_loading",
          "severity": "moderate",
          "action": "exclude",
          "affected_activities": ["barbell_back_squat", "barbell_overhead_press_standing", "conventional_deadlift"]
        },
        {
          "condition": "loaded_spinal_flexion",
          "severity": "high",
          "action": "exclude",
          "affected_activities": ["sit_up", "crunch", "jefferson_curl", "good_morning"]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 3,
        "min_minutes_per_day": 55,
        "max_minutes_per_day": 75
      }
    },
    "personalization": {
      "inputs": [
        {
          "id": "sleep_hours",
          "type": "number",
          "source": "wellness.sleep_hours_last_night",
          "label": "Hours slept last night"
        },
        {
          "id": "session_rpe_yesterday",
          "type": "number",
          "source": "wellness.session_rpe_yesterday",
          "label": "RPE of last session"
        },
        {
          "id": "subjective_readiness",
          "type": "number",
          "source": "wellness.subjective_readiness",
          "label": "Subjective readiness (1-10)"
        }
      ],
      "rules": [
        {
          "id": "rule-low-readiness-deload",
          "condition": {
            "field": "wellness.subjective_readiness",
            "op": "lte",
            "value": 4
          },
          "actions": [
            {
              "type": "modify_intensity",
              "scope": "session",
              "adjustment": "reduce_weight_pct",
              "value": 10
            }
          ]
        },
        {
          "id": "rule-poor-sleep-reduce-volume",
          "condition": {
            "field": "wellness.sleep_hours_last_night",
            "op": "lt",
            "value": 6
          },
          "actions": [
            {
              "type": "modify_volume",
              "scope": "session",
              "adjustment": "drop_last_set_each_exercise"
            }
          ]
        }
      ]
    },
    "athlete_thresholds": {
      "body_weight_kg": 85
    },
    "phases": [
      {
        "id": "phase-1-foundation",
        "name": "Phase 1 — Foundation & Movement Quality",
        "order": 1,
        "type": "accumulation",
        "description": "Weeks 1–3. Establish movement patterns, build connective tissue tolerance, and reinforce spine-sparing technique. Moderate loads, higher rep ranges, focus on form. RPE cap 7.",
        "duration": { "value": 3, "unit": "weeks" },
        "weeks": [
          {
            "id": "p1-w1",
            "name": "Week 1",
            "order": 1,
            "days": [
              {
                "id": "p1-w1-d1",
                "day_of_week": 1,
                "type": "training",
                "name": "Day A — Lower Body + Core",
                "estimated_duration_minutes": 65,
                "blocks": [
                  {
                    "id": "p1-w1-d1-b1",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1-w1-d1-wu1",
                        "type": "simple",
                        "name": "5-min bike or brisk walk",
                        "duration": { "value": 5, "unit": "minutes" }
                      },
                      {
                        "id": "p1-w1-d1-wu2",
                        "type": "recovery",
                        "name": "Hip & Thoracic Mobility Warm-up",
                        "category": "mobility",
                        "prescription": {
                          "duration": { "value": 8, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "wu-hip-90-90",
                              "type": "recovery_exercise",
                              "name": "90/90 Hip Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 2,
                              "sides": "both",
                              "body_part": "hip_flexors"
                            },
                            {
                              "id": "wu-thoracic-rotation",
                              "type": "recovery_exercise",
                              "name": "Thoracic Rotation (quadruped)",
                              "modality": "mobility_drill",
                              "reps": 10,
                              "sides": "both",
                              "body_part": "thoracic_spine"
                            },
                            {
                              "id": "wu-glute-bridge",
                              "type": "recovery_exercise",
                              "name": "Glute Bridge (bodyweight activation)",
                              "modality": "dynamic_stretch",
                              "reps": 15,
                              "body_part": "glutes"
                            },
                            {
                              "id": "wu-banded-clamshell",
                              "type": "recovery_exercise",
                              "name": "Banded Clamshell",
                              "modality": "dynamic_stretch",
                              "reps": 15,
                              "sides": "both",
                              "body_part": "hip_abductors"
                            }
                          ]
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1-w1-d1-b2",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "p1-w1-d1-a1",
                        "type": "exercise",
                        "exercise_ref": "goblet_squat",
                        "name": "Goblet Squat",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "unit": "kg" }
                        },
                        "target_rpe": 6,
                        "primary_muscles": ["quadriceps", "glutes"],
                        "secondary_muscles": ["hamstrings", "calves", "abs"],
                        "movement_pattern": "squat"
                      },
                      {
                        "id": "p1-w1-d1-a2",
                        "type": "exercise",
                        "exercise_ref": "trap_bar_rdl",
                        "name": "Trap Bar Romanian Deadlift",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "unit": "kg" }
                        },
                        "target_rpe": 6,
                        "primary_muscles": ["hamstrings", "glutes"],
                        "secondary_muscles": ["spinal_erectors", "traps"],
                        "movement_pattern": "hinge"
                      },
                      {
                        "id": "p1-w1-d1-a3",
                        "type": "exercise",
                        "exercise_ref": "db_reverse_lunge",
                        "name": "Dumbbell Reverse Lunge",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "unit": "kg" }
