                      {
                        "id": "p1-w1-d1-a5",
                        "type": "exercise",
                        "exercise_ref": "dead_bug",
                        "name": "Dead Bug",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 8, "max": 10 },
                          "rest": { "value": 60, "unit": "seconds" },
                          "weight": { "type": "bodyweight" }
                        },
                        "target_rpe": 5,
                        "primary_muscles": ["abs"],
                        "secondary_muscles": ["hip_flexors"],
                        "movement_pattern": "anti_rotate"
                      }
                    ]
                  },
                  {
                    "id": "p1-w1-d1-b3",
                    "type": "cooldown",
                    "order": 3,
                    "activities": [
                      {
                        "id": "p1-w1-d1-cd1",
                        "type": "recovery",
                        "name": "Lower Body Cooldown Stretches",
                        "category": "flexibility",
                        "prescription": {
                          "duration": { "value": 8, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "cd-hip-flexor-stretch",
                              "type": "recovery_exercise",
                              "name": "Kneeling Hip Flexor Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 40,
                              "reps": 2,
                              "sides": "both",
                              "intensity_rpe": 6,
                              "body_part": "hip_flexors"
                            },
                            {
                              "id": "cd-hamstring-stretch",
                              "type": "recovery_exercise",
                              "name": "Supine Hamstring Stretch (strap)",
                              "modality": "static_stretch",
                              "hold_seconds": 40,
                              "reps": 2,
                              "sides": "both",
                              "intensity_rpe": 6,
                              "body_part": "hamstrings"
                            },
                            {
                              "id": "cd-foam-roll-thoracic",
                              "type": "recovery_exercise",
                              "name": "Foam Roll Thoracic Spine",
                              "modality": "smr_foam_roll",
                              "hold_seconds": 60,
                              "body_part": "thoracic_spine"
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "p1-w1-d2",
                "day_of_week": 3,
                "type": "training",
                "name": "Day B — Upper Body Push + Pull",
                "estimated_duration_minutes": 65,
                "blocks": [
                  {
                    "id": "p1-w1-d2-b1",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1-w1-d2-wu1",
                        "type": "simple",
                        "name": "5-min row or bike",
                        "duration": { "value": 5, "unit": "minutes" }
                      },
                      {
                        "id": "p1-w1-d2-wu2",
                        "type": "recovery",
                        "name": "Shoulder & Thoracic Warm-up",
                        "category": "mobility",
                        "prescription": {
                          "duration": { "value": 7, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "wu-band-pull-apart",
                              "type": "recovery_exercise",
                              "name": "Band Pull-Apart",
                              "modality": "dynamic_stretch",
                              "reps": 15,
                              "body_part": "rear_delts"
                            },
                            {
                              "id": "wu-wall-slide",
                              "type": "recovery_exercise",
                              "name": "Wall Slide",
                              "modality": "mobility_drill",
                              "reps": 10,
                              "body_part": "thoracic_spine"
                            },
                            {
                              "id": "wu-cat-cow",
                              "type": "recovery_exercise",
                              "name": "Cat-Cow (gentle spinal mobility)",
                              "modality": "dynamic_stretch",
                              "reps": 10,
                              "body_part": "thoracic_spine"
                            }
                          ]
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1-w1-d2-b2",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "p1-w1-d2-a1",
                        "type": "exercise",
                        "exercise_ref": "db_incline_bench_press",
                        "name": "Dumbbell Incline Bench Press",
                        "prescription": {
                          "type": "sets_reps",
