                        "type": "exercise",
                        "exercise_ref": "seated_cable_row",
                        "name": "Seated Cable Row (neutral grip)",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "unit": "kg" }
