                          "weight": { "type": "absolute", "unit": "kg" }
                        },
                        "target_rpe": 6,
                        "primary_muscles": ["front_delts", "side_delts"],
                        "secondary_muscles": ["triceps", "traps"],
                        "movement_pattern": "push_vertical"
                      },
                      {
                        "id": "p1-w1-d2-a4",
                        "type": "exercise",
                        "exercise_ref": "lat_pulldown_neutral",
                        "name": "Lat Pulldown (neutral grip)",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "unit": "kg" }
                        },
                        "target_rpe": 6,
