                        "name": "Cable Face Pull",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 15, "max": 20 },
                          "rest": { "value": 60, "unit": "seconds" },
                          "weight": { "type": "absolute", "unit": "kg" }
                        },
                        "target_rpe": 5,
                        "primary_muscles": ["rear_delts", "traps"],
                        "secondary_muscles": ["upper_back"],
                        "movement_pattern": "pull_horizontal"
                      }
                    ]
                  },
                  {
                    "id": "p1-w1-d2-b3",
                    "type": "cooldown",
                    "order": 3,
                    "activities": [
                      {
                        "id": "p1-w1-d2-cd1",
                        "type": "recovery",
                        "name": "Upper Body Cooldown",
                        "category": "flexibility",
                        "prescription": {
                          "duration": { "value": 7, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "cd-chest-doorway",
                              "type": "recovery_exercise",
                              "name": "Doorway Chest Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 40,
                              "reps": 2,
                              "sides": "both",
                              "intensity_rpe": 5,
                              "body_part": "chest"
                            },
                            {
                              "id": "cd-lat-stretch",
                              "type": "recovery_exercise",
                              "name": "Lat Stretch (overhead reach on bench)",
                              "modality": "static_stretch",
                              "hold_seconds": 40,
                              "reps": 2,
                              "sides": "both",
                              "intensity_rpe": 5,
                              "body_part": "lats"
                            }
                          ]
                        }
