                ]
              },
              {
                "id": "p1-w1-d3",
                "day_of_week": 5,
                "type": "training",
                "name": "Day C — Full Body + Carries",
                "estimated_duration_minutes": 65,
                "blocks": [
                  {
                    "id": "p1-w1-d3-b1",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1-w1-d3-wu1",
                        "type": "simple",
                        "name": "5-min bike or treadmill walk",
                        "duration": { "value": 5, "unit": "minutes" }
                      },
                      {
                        "id": "p1-w1-d3-wu2",
                        "type": "recovery",
                        "name": "Full Body Activation",
                        "category": "mobility",
                        "prescription": {
                          "duration": { "value": 7, "unit": "minutes" },
