                  },
                  {
                    "id": "p1-w1-d3-b2",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "p1-w1-d3-a1",
                        "type": "exercise",
                        "exercise_ref": "trap_bar_deadlift_low_handles",
                        "name": "Trap Bar Deadlift (low handles, moderate load)",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 8, "max": 10 },
