                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "unit": "kg" }
                        },
                        "target_rpe": 6,
                        "primary_muscles": ["lats", "upper_back"],
                        "secondary_muscles": ["biceps", "rear_delts"],
                        "movement_pattern": "pull_horizontal"
                      },
                      {
                        "id": "p1-w1-d3-a4",
                        "type": "exercise",
                        "exercise_ref": "farmers_carry",
                        "name": "Farmer's Carry (dumbbells)",
                        "prescription": {
                          "type": "time",
                          "sets": 3,
                          "duration": { "value": 30, "unit": "seconds" },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "unit": "kg" }
                        },
                        "target_rpe": 6,
                        "primary_muscles": ["traps", "forearms"],
                        "secondary_muscles": ["abs", "glutes", "calves"],
                        "movement_pattern": "carry"
                      },
                      {
                        "id": "p1-w1-d3-a5",
                        "type": "exercise",
                        "exercise_ref": "bird_dog",
                        "name": "Bird Dog",
                        "prescription": {
                          "type": "sets_reps",
